local M = class("AlipayActivityNode", LikeOO.OOUIbase)
--支付宝红包
M.m_uiName = "GiftBag/AlipayActivityNode"
M.cacheSpineName = ""
function M:onEnter()
    self:showUI(false)
    self.m_end_ts = 0
    self:refreshUI()
    self:bindUI()
end

function M:bindUI()
    self:setTextByLanKey("text_hintText1", "bag_text_0004")
    self:setTextByLanKey("text_hintText2", "bag_text_0005")
end

function M:switchInit(url, callback, id)
    local function callFunc(data)
        if callback then
            callback(data)
        end
        if data and data["end"] == 1 then
            return
        end
        self:refreshUI()
    end
    self.id = id
    self.m_model:initData2(url, callFunc)
    RedPointUtil:saveLocalRedPointFreshTime("AlipayRedBagActivityRedDot")
end

function M:switchUI(id)
    self.id = id
    self:refreshUI()
end


function M:refreshUI()
    self:showUI(true)
    self.m_end_ts = self.m_model:getActivityEndTime(self.id)
    RedPointUtil:saveLocalRedPointFreshTime("AlipayRedBagActivityRedDot")
end

function M:showUI(bl)
    self:setTextByLanKey("text_btn_jumpBtnText", "castingSword_str_0049")
    self:setTextByLanKey("text_btn_gotBtnText", "castingSword_str_0048")
end

function M:onButtonClick(obj, name)
    if name == "btn_infoBtn" then
        self.m_control:openView("GiftBag.AlipayActivityPop")
    elseif name == "btn_jumpBtn" then
        -- 跳转充值
        QuickOpenFuncUtil:openFunc(10037)
        self.m_control:closeView()
    elseif name == "btn_gotBtn" then
        -- 跳转超链接
        local url = nil
        local active_tab = ConfigManager:getCfgByName("active")
        for i, v in pairs(active_tab) do
            if v.open_id == 217 then
                url = v.link
                break
            end
        end
        if url ~= nil then
            local url_new = url
            SDKUtil:openUrl(url_new)
        end
        M.super.onButtonClick(self, obj, name)
    end
end

function M:destroy()
    M.super.destroy(self)
end


return M